const data = $input.first().json;
const workflowName = (data.workflow && data.workflow.name) || 'unknown workflow';
const executionId = (data.execution && data.execution.id) || null;
const executionUrl = (data.execution && data.execution.url) || '';
const failedNode = (data.execution && data.execution.lastNodeExecuted) || 'unknown node';
const errorMessage = ((data.execution && data.execution.error && data.execution.error.message) || 'unknown error').toString().slice(0, 500);

const staticData = $getWorkflowStaticData('global');
if (!staticData.failureCounts) staticData.failureCounts = {};
staticData.failureCounts[workflowName] = (staticData.failureCounts[workflowName] || 0) + 1;
const failureCount = staticData.failureCounts[workflowName];

return [{
  json: {
    workflow_name: workflowName,
    n8n_execution_id: executionId,
    execution_url: executionUrl,
    failed_node: failedNode,
    error_message: errorMessage,
    failure_count: failureCount,
    is_repeated_failure: failureCount >= 3 && failureCount % 3 === 0
  }
}];

